import { HttpConnection, IHttpVerb } from '@clean-rn/shared/infrastructure';
import {
  IDocumentProperties,
  IDocumentRepository,
  DocumentVO,
  IDocumentStatus,
  IDocumentCategory,
} from '@clean-rn/kyc/domain';
import { IDocumentServer } from '../types';

export class KycApi implements IDocumentRepository {
  private static instance: KycApi | null = null;
  private connection: HttpConnection;

  // Make the constructor private to prevent direct instantiation
  private constructor(httpConnection: HttpConnection) {
    this.connection = httpConnection;
    this.getDocuments = this.getDocuments.bind(this);
  }

  // Public method to provide access to the singleton instance
  public static getInstance(httpConnection: HttpConnection): KycApi {
    if (!this.instance) {
      this.instance = new KycApi(httpConnection);
    }
    return this.instance;
  }

  async getDocuments(): Promise<IDocumentProperties[]> {
    const response = await fetch(
      `${this.connection.baseUrl}/app/document/kyc`,
      this.connection.options(IHttpVerb.GET),
    );
    await this.connection.handleError(response);
    const documents = await response.json();
    return documents.map((doc: IDocumentServer) => ({
      category: IDocumentCategory[doc.documentContext as keyof typeof IDocumentCategory],
      typeId: doc.documentTypeId,
      status: IDocumentStatus[doc.documentStatus as keyof typeof IDocumentStatus],
      name: doc.name,
      createdAt: new Date(doc.createdAt),
    }));
  }

  async createDocument({
    customerId,
    document,
  }: {
    customerId: string;
    document: DocumentVO;
  }): Promise<DocumentVO> {
    const params = {
      documentContext: document.properties.category,
      documentTypeId: document.properties.typeId,
      name: document.properties.name,
      userId: customerId,
      fileContentBase64: document.value.recto,
    };
    console.log('size params', calculateBase64Size(document.value.recto));
    const params2 = {
      documentContext: IDocumentCategory.FIRST_ID,
      documentTypeId: 17,
      name: 'test-mock',
      userId: 3537985,
      fileContentBase64:
        '',
    };
    console.log('size params 2', calculateBase64Size(params2['fileContentBase64']));

    console.log('---------------');
    console.log('createDocument params');
    console.log('params', params2['name']);
    const responseRecto = await fetch(
      `${this.connection.baseUrl}/app/document/kyc`,
      this.connection.options(IHttpVerb.POST, params),
    );
    console.log('responseRecto', responseRecto);
    await this.connection.handleError(responseRecto);
    const documentServer = await responseRecto.json();
    const documentProperties = {
      category: IDocumentCategory[documentServer.documentContext as keyof typeof IDocumentCategory],
      typeId: documentServer.documentTypeId,
      status: IDocumentStatus[documentServer.documentStatus as keyof typeof IDocumentStatus],
      name: documentServer.name,
      createdAt: new Date(documentServer.createdAt),
    };
    const documentResponse = new DocumentVO(documentProperties);
    if (document.value.recto) documentResponse.addPage(document.value.recto);
    if (document.value.verso) documentResponse.addPage(document.value.verso);

    return documentResponse;
    // if (!document.value.verso) {
    //   return [responseRecto.json()];
    // } else {
    //   const responseVerso = await fetch(
    //     `${this.connection.baseUrl}/app/document/kyc`,
    //     this.connection.options(IHttpVerb.POST, { ...params, fileContentBase64: document.value.verso }),
    //   );
    //   await this.connection.handleError(responseVerso);
    //   return [responseRecto.json(), responseVerso.json()];
    // }
  }
}
function calculateBase64Size(base64String: string) {
  // Remplacer les caractères non-Base64 par du vide (pour la sécurité)
  const cleanedBase64String = base64String.replace(/[^A-Za-z0-9+/=]/g, '');

  // Calculer la taille en octets de la chaîne Base64
  const base64Length = cleanedBase64String.length;

  // Trouver et soustraire le nombre de caractères de remplissage
  const padding = (cleanedBase64String.match(/=/g) || []).length;

  // Calculer la taille réelle des données binaires
  return ((base64Length - padding) * 3) / 4;
}
